$('optimize').onclick=async()=>{const token=++scanToken, snapshot=clone(s);playing=false;$('optimize').disabled=true;$('cancelSearch').hidden=false;text('report','Recherche des permutations et orientations…');try{const r=await B.findSequence(snapshot,{yieldTask:()=>new Promise(resolve=>setTimeout(resolve,0)),cancel:()=>token!==scanToken});if(token!==scanToken)return;if(r.status==='found'){s.order=r.order;s.flips=r.flips;step=0;save();invalidate();text('report',`Séquence appliquée : ${r.attempts} essais, aucun conflit détecté aux positions échantillonnées. Manipulations entre plis non contrôlées.`)}else text('report',r.status==='limit'?`Limite de recherche atteinte (8 plis / 160 essais). Aucun résultat garanti.`:`Aucune séquence trouvée dans ce modèle (${r.attempts} essais).`)}finally{if(token===scanToken){$('optimize').disabled=false;$('cancelSearch').hidden=true}}};
