for(const [id,mode] of [['bothViews','both'],['foldedView','fold'],['flatView','flat'],['volumeView','volume']])$(id).onclick=()=>setPreview(mode);

function getRadius(){const thickness=num('radiusThickness');if(!bounded(thickness,.1,50))throw Error('Épaisseur de 0,1 à 50 mm.');return B.radiusPlan({radius:num('radiusValue'),reference:$('radiusRef').value,sweep:num('radiusSweep'),thickness,mode:$('radiusMode').value,insideAngle:num('radiusAngle'),count:num('radiusCount'),lead:num('radiusLead'),tail:num('radiusTail'),sign:num('radiusSign')})}
function drawRadius(){if(tab!=='radius')return;const countMode=$('radiusMode').value==='count';$('radiusAngleLabel').hidden=countMode;$('radiusCountLabel').hidden=!countMode;const {c,w,h}=canvas('radiusDrawing');grid(c,w,h);$('radiusStations').replaceChildren();try{const r=getRadius(),pts=B.profile(r.lengths,r.turns),m=mapping(pts,w,h,38);path(c,pts.map(m.project),null,'#59e5f3',3,false);for(let i=1;i<pts.length-1;i++){const a=m.project(pts[i]);c.beginPath();c.arc(...a,3,0,Math.PI*2);c.fillStyle='#f3b94e';c.fill();if(r.count<12||i%3===1)label(c,`P${i}`,[a[0]+5,a[1]-6],'#f3b94e')}text('radiusResult',`${r.count} pli(s) à ${fmt(r.insideAngle)}° int. · pas ${fmt(r.pitch)} mm · arc lisse ${fmt(r.arc)} mm · flan polygonal ${fmt(r.polygonLength)} mm · écart radial maxi ${fmt(r.error)} mm (sommets)`);const notes=[`Rayon à mi-épaisseur : ${fmt(r.radius)} mm. V monté : ${fmt(s.die.v)} mm.`];if(r.count>1&&r.pitch<s.die.v)notes.push('Pas inférieur à l’ouverture V : contrôler appui et reprise des plis précédents, risque de contact mal modélisé.');if(Math.min(r.lengths[0],r.lengths[r.lengths.length-1])<s.die.v/2)notes.push('Extrémité plus courte que le demi-V : appui à vérifier.');if($('radiusBlank').value!==''){const b=num('radiusBlank');if(!bounded(b,.1,100000))throw Error('Largeur de flan invalide.');const diff=b-r.polygonLength;notes.push(`Flan disponible − flan théorique : ${fmt(diff)} mm${diff<-.001?' (manque théorique)':''}.`)}text('radiusWarning',notes.join(' '));const table=document.createElement('table');const head=document.createElement('tr');for(const title of ['Pli','Position (mm)','Angle int.']){const th=document.createElement('th');th.textContent=title;head.append(th)}table.append(head);r.stations.forEach((station,i)=>{const row=document.createElement('tr');for(const value of [`P${i+1}`,fmt(station),fmt(r.insideAngle)+'°']){const td=document.createElement('td');td.textContent=value;row.append(td)}table.append(row)});$('radiusStations').append(table);$('radiusApply').disabled=false}catch(err){text('radiusResult',err.message);text('radiusWarning','');$('radiusApply').disabled=true}}
for(const id of ['radiusValue','radiusRef','radiusSweep','radiusThickness','radiusMode','radiusAngle','radiusCount','radiusLead','radiusTail','radiusSign','radiusBlank'])$(id).oninput=drawRadius;
$('radiusApply').onclick=()=>{try{const r=getRadius();show('piece');draft=draftFrom(r);$('thickness').value=num('radiusThickness');renderDraft();drawPiece();text('pieceMsg','Rayon polygonal créé. Vérifier les dimensions puis appliquer la pièce pour simuler chaque pli.')}catch(err){text('radiusResult',err.message)}};
$('addSide').onclick=()=>{if(draft.length>=31)return;draft.push({length:50,angle:90,sign:1});renderDraft();drawPiece()};
function applyDraft(simulate=false){try{const {lengths,turns}=currentProfile(),next={...s,lengths,turns,order:turns.map((_,i)=>i),flips:turns.map(()=>false),t:num('thickness'),width:num('width'),material:$('material').value};if(!valid(next))throw Error('Valeurs invalides. Vérifier les dimensions et les angles.');const same=JSON.stringify(lengths)===JSON.stringify(s.lengths)&&JSON.stringify(turns)===JSON.stringify(s.turns);if(same){next.order=s.order.slice();next.flips=s.flips.slice()}s=next;step=0;invalidate();const saved=save();text('pieceMsg',saved?(same?'Pièce enregistrée, séquence conservée.':'Pièce enregistrée, séquence réinitialisée.'):'Pièce appliquée, sauvegarde locale indisponible.');if(simulate)show('sim');return true}catch(err){text('pieceMsg',err.message);return false}}
$('applyPiece').onclick=()=>applyDraft();$('simulatePiece').onclick=()=>applyDraft(true);
const gaugeKeys=['x','r','retract','depth','height','minX','maxX'];function loadMachine(){for(const k of machineKeys)$(k).value=s[k];$('gaugeMode').value=s.gauge.mode;for(const k of gaugeKeys)$('gauge_'+k).value=s.gauge[k];renderPresets();text('machineMsg','')}$('applyMachine').onclick=()=>{const next={...s,machineName:$('machineName').value.trim()||'Presse générique'};for(const k of machineKeys.filter(k=>k!=='machineName'))next[k]=num(k);next.gauge={mode:$('gaugeMode').value,...Object.fromEntries(gaugeKeys.map(k=>[k,num('gauge_'+k)]))};if(!valid(next)){text('machineMsg','Dimensions invalides.');return}s=next;invalidate();text('machineMsg',save()?'Plieuse enregistrée.':'Plieuse appliquée, sauvegarde locale indisponible.')};
function renderPresets(){const sel=$('machinePresets');sel.replaceChildren();s.machines.forEach((m,i)=>{const o=document.createElement('option');o.value=i;o.textContent=m.machineName;sel.append(o)});$('loadPreset').disabled=$('deletePreset').disabled=!s.machines.length;}
$('savePreset').onclick=()=>{const next=machineData(s),i=s.machines.findIndex(m=>m.machineName===next.machineName);if(i>=0)s.machines[i]=next;else if(s.machines.length<50)s.machines.push(next);else return text('machineMsg','Bibliothèque pleine (50 presses).');renderPresets();text('machineMsg',save()?'Presse active mémorisée.':'Sauvegarde indisponible.')};
$('loadPreset').onclick=()=>{const m=s.machines[Number($('machinePresets').value)];if(!m)return;s={...s,...m};invalidate();loadMachine();save();text('machineMsg','Presse chargée.')};$('deletePreset').onclick=()=>{if(!s.machines.length)return;s.machines.splice(Number($('machinePresets').value),1);renderPresets();save();};
function svgTool(tool){const ns='http://www.w3.org/2000/svg',el=document.createElementNS(ns,'svg'),poly=document.createElementNS(ns,'polygon'),xs=tool.poly.map(p=>p[0]),ys=tool.poly.map(p=>-p[1]),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y,pad=Math.max(w,h)*.12;el.setAttribute('viewBox',`${x-pad} ${y-pad} ${w+pad*2} ${h+pad*2}`);poly.setAttribute('points',tool.poly.map(p=>`${p[0]},${-p[1]}`).join(' '));poly.setAttribute('fill','#bf913d');poly.setAttribute('stroke','#f4c86b');poly.setAttribute('stroke-width',Math.max(w,h)/120);el.append(poly);return el}
function catalog(){const host=$('catalog');host.replaceChildren();text('selectedTools',`Montés : ${s.punch.name} + ${s.die.name}`);const query=$('toolSearch').value.trim().toLowerCase();const tools=[...base,...s.custom].filter(t=>t.name.toLowerCase().includes(query)).filter(t=>($('brandFilter').value==='Tous'||t.brand===$('brandFilter').value)&&($('typeFilter').value==='Tous'||t.type===$('typeFilter').value));if(!tools.length){const p=document.createElement('p');p.textContent='Aucun profil enregistré pour ce filtre. Ajouter un outil depuis Mes outils.';host.append(p)}for(const t of tools){const card=document.createElement('div');card.className='toolcard';const title=document.createElement('strong');title.textContent=t.name;const p=document.createElement('p');p.textContent=`${t.brand} · ${t.type==='die'?'Matrice':'Poinçon'} · ${t.angle}°${t.type==='die'?' · V'+t.v:''}`;const source=document.createElement('p');source.textContent=t.source||'Dimensions saisies localement, non vérifiées';const btn=document.createElement('button');btn.textContent=s[t.type].id===t.id?'Monté':'Monter cet outil';btn.disabled=s[t.type].id===t.id;btn.onclick=()=>{s[t.type]=clone(t);save();invalidate();catalog()};card.append(svgTool(t),title,p,source,btn);if(s.custom.some(x=>x.id===t.id)){const edit=document.createElement('button');edit.textContent='Modifier / dupliquer';edit.onclick=()=>{show('custom');$('toolName').value=t.name;$('toolBrand').value=t.brand;$('toolType').value=t.type;$('toolAngle').value=t.angle;$('toolV').value=t.v||16;$('toolHeight').value=Math.max(...t.poly.map(p=>Math.abs(p[1])));$('toolWidth').value=Math.max(...t.poly.map(p=>p[0]))-Math.min(...t.poly.map(p=>p[0]));$('toolSource').value=t.source||'';$('toolPoly').value=t.poly.map(p=>p.join(',')).join('\n');toolPreview()};card.append(edit);const del=document.createElement('button');del.textContent='Supprimer';del.disabled=s[t.type].id===t.id;del.onclick=()=>{s.custom=s.custom.filter(x=>x.id!==t.id);save();catalog()};card.append(del)}host.append(card)}renderManufacturer(query)}
function renderManufacturer(query){const host=$('manufacturerCatalog');host.replaceChildren();for(const t of window.ManufacturerTools.filter(t=>t.name.toLowerCase().includes(query)&&($('brandFilter').value==='Tous'||t.brand===$('brandFilter').value)&&($('typeFilter').value==='Tous'||t.type===$('typeFilter').value))){const card=document.createElement('div');card.className='toolcard';const title=document.createElement('strong');title.textContent=t.brand+' · '+t.name;const info=document.createElement('p');info.textContent=[`${t.angle}°`,t.v&&`V${t.v}`,t.h&&`H ${t.h} mm`,t.w&&`Larg. ${t.w} mm`,`R ${t.r} mm`,`Long. ${t.length} mm`].filter(Boolean).join(' · ');const note=document.createElement('p');note.textContent='Cotes nominales uniquement · contour à relever';const btn=document.createElement('button');btn.textContent='Préparer mon contour';btn.onclick=()=>{show('custom');$('toolName').value=t.name;$('toolBrand').value=t.brand;$('toolType').value=t.type;$('toolAngle').value=t.angle;$('toolV').value=t.v||'';$('toolHeight').value=t.h||'';$('toolWidth').value=t.w||'';$('toolSource').value='Cotes nominales : '+t.source+' — contour utilisateur non certifié';$('toolPoly').value='';drawMode=true;updateDraw();toolPreview();text('toolMsg','Saisir le contour réel avant enregistrement. Les cotes manquantes doivent être mesurées.')};const source=document.createElement('p');source.className='source';source.textContent=t.source;card.append(title,info,note,source,btn);host.append(card)}}
$('toolSearch').oninput=catalog;
$('brandFilter').onchange=catalog;$('typeFilter').onchange=catalog;
function readPoly(){if(!$('toolPoly').value.trim())return [];return $('toolPoly').value.trim().split(/\n+/).map(line=>line.trim().split(/[,;\s]+/).map(Number))}
function generate(){const h=num('toolHeight'),w=num('toolWidth'),a=num('toolAngle'),v=num('toolV'),die=$('toolType').value==='die';if(!bounded(h,1,1000)||!bounded(w,1,1000)||!bounded(a,10,170)||(die&&(!bounded(v,1,w-1)))){text('toolMsg','Dimensions invalides (V inférieur à la largeur).');return}const p=die?B.die(v,h,w,a):B.punch(h,w,a,$('toolShape').value==='goose');$('toolPoly').value=p.map(q=>q.map(x=>Number(x.toFixed(4))).join(',')).join('\n');text('toolMsg','Contour générique généré, à vérifier et corriger selon les cotes réelles.');toolPreview()}
function updateDraw(){text('drawTool',`Dessin point par point : ${drawMode?'activé':'désactivé'}`)}
function toolPreview(){if(tab!=='custom')return;const {c,w,h}=canvas('toolDrawing');grid(c,w,h);const poly=readPoly().filter(q=>q.length===2&&q.every(Number.isFinite)),extent=Math.max(10,Math.min(1000,num('toolExtent')||200)),die=$('toolType').value==='die';const m=drawMode?mapping([[-extent/2,die?-extent:0],[extent/2,die?0:extent]],w,h,22):mapping(poly.length?poly:[[0,0],[1,1]],w,h);toolMap=m;const o=m.project([0,0]);path(c,[[0,o[1]],[w,o[1]]],null,'#6b8191',1,false);path(c,[[o[0],0],[o[0],h]],null,'#6b8191',1,false);label(c,'0,0',[o[0]+5,o[1]-5]);const valid=B.validPoly(poly);path(c,poly.map(m.project),valid?'#b17e2b':null,valid?'#f2c76a':'#ff8585',2,valid);for(const q of poly){const a=m.project(q);c.beginPath();c.arc(...a,3,0,Math.PI*2);c.fillStyle='#fff';c.fill();label(c,`${q[0]},${q[1]}`,[a[0]+4,a[1]-5])}}
$('drawTool').onclick=()=>{drawMode=!drawMode;updateDraw();toolPreview()};$('toolExtent').oninput=toolPreview;$('clearPoly').onclick=()=>{$('toolPoly').value='';toolPreview()};$('undoPoint').onclick=()=>{$('toolPoly').value=$('toolPoly').value.trim().split(/\n+/).slice(0,-1).join('\n');toolPreview()};$('toolDrawing').onclick=e=>{if(!drawMode||!toolMap)return;const rect=$('toolDrawing').getBoundingClientRect(),snap=num('toolSnap');if(!bounded(snap,.1,50))return;const q=toolMap.unproject([e.clientX-rect.left,e.clientY-rect.top]).map(v=>Number((Math.round(v/snap)*snap).toFixed(4)));const poly=readPoly();if(poly.length>=100)return;poly.push(q);$('toolPoly').value=poly.map(p=>p.join(',')).join('\n');toolPreview()};
$('generate').onclick=generate;$('toolPoly').oninput=toolPreview;$('toolType').onchange=()=>{const die=$('toolType').value==='die';$('toolHeight').value=die?55:100;$('toolWidth').value=die?60:32;generate()};$('saveTool').onclick=()=>{const tool={id:'local-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),name:$('toolName').value.trim(),brand:$('toolBrand').value,type:$('toolType').value,angle:num('toolAngle'),v:$('toolType').value==='die'?num('toolV'):0,poly:readPoly(),source:$('toolSource').value.trim()||'Dimensions utilisateur non vérifiées'};if(!toolValid(tool)||s.custom.length>=200){text('toolMsg','Contour ou dimensions invalides, ou bibliothèque pleine.');return}s.custom.push(tool);text('toolMsg',save()?'Outil ajouté au catalogue.':'Outil ajouté, sauvegarde locale indisponible.')};
$('export').onclick=()=>{const data=JSON.stringify({version:1,project:s},null,2);if(window.NativeFiles){window.NativeFiles.save(data);return}const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='pliage-machine-projet.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);text('fileMsg','Export demandé.')};$('import').onchange=async()=>{try{const file=$('import').files[0];if(!file)return;if(file.size>3000000)throw Error('Fichier trop volumineux');const obj=JSON.parse(await file.text());if(obj.version!==1||!obj.project||!valid(migrate(obj.project)))throw Error('Structure de projet invalide');s=migrate(obj.project);step=0;invalidate();text('fileMsg',save()?'Projet importé et enregistré.':'Projet importé, sauvegarde locale indisponible.')}catch(e){text('fileMsg','Import refusé : '+e.message)}finally{$('import').value=''}};$('reset').onclick=()=>{if(!confirm('Réinitialiser la pièce et la plieuse ?'))return;const {custom,machines,flat}=s;s={...defaults(),custom,machines,...(flat?{flat}:{})};step=0;invalidate();save();text('fileMsg','Configuration réinitialisée.')};window.addEventListener('resize',()=>{if(tab==='sim')render();if(tab==='piece')drawPiece();if(tab==='radius')drawRadius();if(tab==='custom')toolPreview()});$('scene').classList.toggle('orbit',true);$('yaw').value=defaultView.yaw; $('pitch').value=defaultView.pitch; $('zoom').value=defaultView.zoom; text('status','Rendu atelier 3D indicatif'); generate();show('sim');
